INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'CRE.G2.CREATI.SELF_AWARENESS', 'cre', 2, 'State what they like about themselves as God''s creation and list chores they do at home', ARRAY['CRE.G2.CREATI.SELF_AWARENESS.a', 'CRE.G2.CREATI.SELF_AWARENESS.b']::text[], 'States good things about himself or herself (my eyes, my voice, I can run, I help others) as made by God (Psalm 139:13: you knit me together in my mother''s womb), and lists five chores done at home (sweeping, washing utensils, fetching water, making the bed, feeding animals). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a good thing about yourself","what Psalm 139:13 says","name a chore"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'CRE.G2.CREATI.MY_FAMILY', 'cre', 2, 'Name members of the family, nuclear and extended (Acts 10:2)', ARRAY['CRE.G2.CREATI.MY_FAMILY.a']::text[], 'Names family members (father, mother, brothers, sisters) and the extended family (grandparents, uncles, aunts, cousins), says belonging to a family gives love and help, and that Cornelius and all his family worshipped God together (Acts 10:2). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who is this person to you","is this family","nuclear or extended"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS', 'CRE.G2.CREATI.MY_FAMILY', 'cre', 2, 'State items shared at home and four items that should not be shared for healthy living', ARRAY['CRE.G2.CREATI.MY_FAMILY.b', 'CRE.G2.CREATI.MY_FAMILY.c']::text[], 'States items a family shares (food, utensils in turn after washing, chairs, the table, water, books, a radio or TV) to foster unity, and four items that should not be shared for health (toothbrush, towel, comb, underwear, handkerchief, razor blade), because they carry germs from one person to another. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["shared or not shared","why not share it","name an item we share"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'CRE.G2.CREATI.CREATION_OF_THE_SKY_SUN_', 'cre', 2, 'Recognise God as the creator of the sky, sun, moon and stars (Genesis 1:14-19)', ARRAY['CRE.G2.CREATI.CREATION_OF_THE_SKY_SUN_.a']::text[], 'Says God made the lights in the sky on the fourth day (Genesis 1:14-19): the sun to rule the day, the moon to rule the night, and the stars; they mark days, seasons and years; God saw that it was good. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.1.1, CRE.G2.RUBRIC.1.2, CRE.G2.RUBRIC.1.3, CRE.G2.RUBRIC.1.4, CRE.G2.RUBRIC.1.5, CRE.G2.RUBRIC.1.6), never as a phone question: b) draw the sun, moon, and stars to appreciate God’s creation.', '["who made the sun","on which day","what each light does"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE', 'CRE.G2.CREATI.CREATION_OF_THE_SKY_SUN_', 'cre', 2, 'List the importance of reading the Bible (Psalm 119:105)', ARRAY['CRE.G2.CREATI.CREATION_OF_THE_SKY_SUN_.x4']::text[], 'Lists why Christians read the Bible: it is God''s word, it guides how to live (Psalm 119:105: your word is a lamp for my feet, a light on my path), it teaches about God and Jesus, it comforts and helps us pray; and says families can read it together. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.1.1, CRE.G2.RUBRIC.1.2, CRE.G2.RUBRIC.1.3, CRE.G2.RUBRIC.1.4, CRE.G2.RUBRIC.1.5, CRE.G2.RUBRIC.1.6), never as a phone question: e) list the number of times they read the Bible as a family; f) watch a video clip of children reading the Bible; g) in groups sing a song about the Bible, ‘My Bible and I, ooh..........’; h) read and recite Psalms 119:105.', '["why read the Bible","what Psalm 119:105 says","when to read it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT', 'CRE.G2.THE_HO.DIVISIONS_OF_THE_BIBLE', 'cre', 2, 'State the number of books in the Old Testament and identify its first two books', ARRAY['CRE.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.a', 'CRE.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.b']::text[], 'States the Old Testament has 39 books, names Genesis and Exodus as its first two books, and knows the Bible has two divisions (Old and New Testament). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how many books","first book","second book"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL', 'CRE.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_', 'cre', 2, 'Retell the call of Samuel and mention the lesson from it (1 Samuel 3:3-10)', ARRAY['CRE.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.a', 'CRE.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.b']::text[], 'Retells 1 Samuel 3:3-10: the boy Samuel was sleeping in the house of the Lord; the Lord called "Samuel!"; three times he ran to Eli thinking Eli called; Eli understood it was the Lord and told him to answer; the Lord called again and Samuel said "Speak, for your servant is listening." Lesson: listen to God and obey, and answer when called. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who called Samuel","whom Samuel ran to","what Samuel finally said"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL', 'CRE.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH', 'cre', 2, 'Retell the story of Daniel in the den of lions and list lessons from it (Daniel 6)', ARRAY['CRE.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.a', 'CRE.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.b']::text[], 'Retells Daniel 6: officials tricked King Darius into a law that no one should pray to anyone but the king for thirty days; Daniel still prayed three times a day at his open window towards Jerusalem; he was thrown into the den of lions; God sent his angel and shut the lions'' mouths; in the morning Daniel was unharmed and the king praised God. Lessons: pray always, trust God, God protects, be faithful even when it is hard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.2.1, CRE.G2.RUBRIC.2.2, CRE.G2.RUBRIC.2.3, CRE.G2.RUBRIC.2.4, CRE.G2.RUBRIC.2.5, CRE.G2.RUBRIC.2.6), never as a phone question: c) apply lessons learnt in day-to-day life.', '["why Daniel was thrown to the lions","how many times he prayed","who shut the lions'' mouths"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH', 'CRE.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO', 'cre', 2, 'Retell the story of the widow of Zarephath and identify lessons from it (1 Kings 17:7-16)', ARRAY['CRE.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.a', 'CRE.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.b']::text[], 'Retells 1 Kings 17:7-16: in a drought the brook dried up and God sent Elijah to Zarephath; a widow was gathering sticks to cook a last meal from a handful of flour and a little oil for herself and her son; Elijah asked her to make him a small loaf first, promising God would keep the flour and oil from running out; she obeyed, and the flour and oil did not run out until the rain came. Lessons: God provides, share even when we have little, trust and obey God''s word. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the widow had","what Elijah asked","what happened to the flour and oil"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS', 'CRE.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS', 'cre', 2, 'Relate the joy of the shepherds at the birth of Jesus (Luke 2:15-20)', ARRAY['CRE.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.a']::text[], 'Relates Luke 2:15-20: after the angels left, the shepherds hurried to Bethlehem and found Mary, Joseph and the baby lying in a manger; they spread the word about the child; they returned glorifying and praising God for all they had heard and seen. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the shepherds did","how they felt","where they found Jesus"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION', 'CRE.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS', 'cre', 2, 'Describe the dedication of baby Jesus in the temple (Luke 2:22-38)', ARRAY['CRE.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.b']::text[], 'Describes Luke 2:22-38: Mary and Joseph took baby Jesus to the temple in Jerusalem to present him to the Lord; they offered a pair of doves or two young pigeons; Simeon took Jesus in his arms and praised God; Anna the prophetess thanked God and spoke about the child. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where Jesus was taken","what was offered","who held him"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS', 'CRE.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN', 'cre', 2, 'List the three gifts the wise men gave baby Jesus and know to refuse gifts from strangers (Matthew 2:11)', ARRAY['CRE.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.a']::text[], 'Lists the three gifts (gold, frankincense and myrrh, Matthew 2:11), says the wise men gave them out of love and worship, and knows the safety rule for children: politely refuse gifts from strangers and tell a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.3.1, CRE.G2.RUBRIC.3.2, CRE.G2.RUBRIC.3.3, CRE.G2.RUBRIC.3.4, CRE.G2.RUBRIC.3.5, CRE.G2.RUBRIC.3.6), never as a phone question: b) demonstrate assertiveness by refusing gifts from strangers.', '["name a gift","gift from a wise man or a shepherd","what to say to a stranger''s gift"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM', 'CRE.G2.THE_EA.JESUS_CALMS_THE_STORM', 'cre', 2, 'Narrate the miracle of calming the storm and list lessons from it (Matthew 8:23-27)', ARRAY['CRE.G2.THE_EA.JESUS_CALMS_THE_STORM.a', 'CRE.G2.THE_EA.JESUS_CALMS_THE_STORM.b']::text[], 'Narrates Matthew 8:23-27: Jesus and his disciples were in a boat; a furious storm came and waves swept over the boat; Jesus was sleeping; the disciples woke him, "Lord, save us! We''re going to drown!"; he asked why they were afraid, rebuked the winds and waves, and it was completely calm; they were amazed. Lessons: trust Jesus in trouble, call on him, he has power over nature. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where Jesus was","what the disciples said","what Jesus did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH', 'CRE.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH', 'cre', 2, 'Retell the miraculous catch of fish and mention lessons from it (Luke 5:3-9)', ARRAY['CRE.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.a', 'CRE.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.b']::text[], 'Retells Luke 5:3-9: Jesus taught from Simon''s boat; he told Simon to go into deep water and let down the nets; Simon said they had worked all night and caught nothing, but because Jesus said so he would; they caught so many fish the nets began to break and two boats were so full they began to sink; Simon fell at Jesus'' knees. Lessons: obey Jesus, trust him, do not give up, Jesus provides. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Jesus told Simon","how many fish","what Simon said"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND', 'CRE.G2.THE_EA.HEALING_THE_MAN_WITH_A_W', 'cre', 2, 'Retell the healing of the man with a withered hand (Matthew 12:9-13)', ARRAY['CRE.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.a']::text[], 'Retells Matthew 12:9-13: in the synagogue on the Sabbath there was a man with a shrivelled hand; the Pharisees asked if it was lawful to heal on the Sabbath; Jesus said a person would lift a sheep out of a pit on the Sabbath, and it is lawful to do good; he told the man "Stretch out your hand" and it was completely restored. Lesson: show compassion and do good to others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.3.1, CRE.G2.RUBRIC.3.2, CRE.G2.RUBRIC.3.3, CRE.G2.RUBRIC.3.4, CRE.G2.RUBRIC.3.5, CRE.G2.RUBRIC.3.6), never as a phone question: b) mention occasions they prayed to God for healing.', '["where Jesus was","what Jesus told the man","what happened"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_EA.EASTER.EASTER_LOVE', 'CRE.G2.THE_EA.EASTER', 'cre', 2, 'Recognise Jesus'' death as a sign of love and list activities done in church at Easter (1 Corinthians 15:3-4)', ARRAY['CRE.G2.THE_EA.EASTER.a', 'CRE.G2.THE_EA.EASTER.b']::text[], 'Says Jesus died on the cross on Good Friday as a sign of God''s great love (John 3:16), was buried and was raised on the third day (1 Corinthians 15:3-4), and lists activities done in church at Easter: special services, prayers, singing, Bible reading, Palm Sunday processions, sharing with the needy. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["why Jesus died","what happened on the third day","an Easter church activity"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.SHARING.SCHOOL_SHARING', 'CRE.G2.CHRIST.SHARING', 'cre', 2, 'Identify five items shared at school', ARRAY['CRE.G2.CHRIST.SHARING.a']::text[], 'Names items shared at school (books, desks, crayons, balls and play equipment, the library, water, toilets, classroom, food at a party) and says sharing shows kindness and love, and that personal items (toothbrush, handkerchief, water bottle mouthpiece) are not shared for health. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: b) demonstrate kindness by sharing items with others.', '["shared at school or not","name an item we share","why share"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS', 'CRE.G2.CHRIST.OBEDIENCE', 'cre', 2, 'List ways of obeying teachers and the children''s government and discuss reasons (Hebrews 13:17)', ARRAY['CRE.G2.CHRIST.OBEDIENCE.a', 'CRE.G2.CHRIST.OBEDIENCE.b']::text[], 'Lists ways of obeying teachers and the children''s government (prefects, class monitors): follow class rules, listen, do homework, keep time, do duties, keep the class clean; and reasons: they guide and care for us, there is order and safety, God tells us to obey leaders (Hebrews 13:17). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: c) practise obedience in their day-to-day lives.', '["a way of obeying","why obey","obedient or not"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.HONESTY.TELL_TRUTH', 'CRE.G2.CHRIST.HONESTY', 'cre', 2, 'Tell reasons for telling the truth (Proverbs 12:17, 19)', ARRAY['CRE.G2.CHRIST.HONESTY.a']::text[], 'Gives reasons for telling the truth: God wants us to be truthful (Proverbs 12:17, 19: truthful lips endure forever), people trust us, lies lead to more lies and trouble, it keeps friendships; and recognises honest acts (owning up, returning lost items, not copying). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: b) demonstrate responsibility by completing their homework on time; c) practise honesty by taking lost and found items to the teacher or parent.', '["why tell the truth","honest or not","what Proverbs says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS', 'CRE.G2.CHRIST.THANKFULNESS', 'cre', 2, 'List the importance of thanking others (1 Thessalonians 5:18)', ARRAY['CRE.G2.CHRIST.THANKFULNESS.a']::text[], 'Lists why we thank others: it shows we appreciate them, makes them happy, encourages them to help again, builds friendship, and God tells us to give thanks in all circumstances (1 Thessalonians 5:18); and says when to thank (when given something, helped, served food, taught). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: b) demonstrate thankfulness in day-to-day life.', '["why say thank you","when to say thank you","thankful or not"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON', 'CRE.G2.CHRIST.FORGIVENESS', 'cre', 2, 'Know the story of the prodigal son well enough to dramatise it, and its lesson on forgiveness (Luke 15:11-24)', ARRAY['CRE.G2.CHRIST.FORGIVENESS.b']::text[], 'Tells the story of Luke 15:11-24 in order for a drama: the younger son asked for his share, went to a distant country and wasted it; a famine came and he fed pigs; he came to his senses and went home to say sorry; his father ran to him, hugged him, gave him the best robe, a ring and sandals and held a feast. Lesson: God forgives, and we forgive others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: a) practise forgiveness to foster harmonious living.', '["what the younger son did","what the father did","what is the lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS', 'CRE.G2.CHRIST.RESPONSIBILITY', 'cre', 2, 'Mention items they carry to school and how to care for them (Colossians 3:23)', ARRAY['CRE.G2.CHRIST.RESPONSIBILITY.a']::text[], 'Names items carried to school (books, pencils, rubber, ruler, crayons, school bag, water bottle, lunch box, sweater) and how a responsible child cares for them: cover books, keep them in the bag, label them, not lend carelessly, bring them back home; doing it well as for the Lord (Colossians 3:23). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: b) take care of the items they use in school.', '["name an item you carry to school","how to care for it","responsible or careless"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.CHRIST.WORK.HELP_PARENTS', 'CRE.G2.CHRIST.WORK', 'cre', 2, 'Mention how they help parents at home', ARRAY['CRE.G2.CHRIST.WORK.a']::text[], 'Mentions ways children help parents at home (sweeping, washing utensils, fetching water, feeding animals, caring for younger siblings, making the bed, picking litter) and says helping shows love and that work is good. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.4.1, CRE.G2.RUBRIC.4.2, CRE.G2.RUBRIC.4.3, CRE.G2.RUBRIC.4.4, CRE.G2.RUBRIC.4.5, CRE.G2.RUBRIC.4.6, CRE.G2.RUBRIC.4.7, CRE.G2.RUBRIC.4.8, CRE.G2.RUBRIC.4.9), never as a phone question: b) take part in doing simple chores at school and in Church.', '["a way to help at home","helpful or not","why help"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT', 'CRE.G2.THE_CH.PRAYER', 'cre', 2, 'Retell the story of a friend at midnight and know the first lines of the Lord''s Prayer (Luke 11:5-10; Matthew 6:9-10)', ARRAY['CRE.G2.THE_CH.PRAYER.b']::text[], 'Retells Luke 11:5-10: a man went to a friend at midnight asking for three loaves because a traveller had arrived and he had nothing to give; the friend said the door was locked and his children were in bed; because the man kept asking, the friend got up and gave him what he needed; Jesus said "Ask and it will be given to you". Lesson: keep praying. Also knows the first lines of the Lord''s Prayer (Our Father in heaven, hallowed be your name, your kingdom come, your will be done). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G2.RUBRIC.5.1, CRE.G2.RUBRIC.5.2, CRE.G2.RUBRIC.5.3, CRE.G2.RUBRIC.5.4), never as a phone question: a) recite the first four lines of the Lord’s prayer.', '["what the man asked for","why the friend got up","the lesson about prayer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE', 'CRE.G2.THE_CH.THE_HOLY_SPIRIT', 'cre', 2, 'State the promise Jesus gave his disciples and mention three roles of the Holy Spirit (Acts 1:4; Luke 24:49; John 14:26)', ARRAY['CRE.G2.THE_CH.THE_HOLY_SPIRIT.a', 'CRE.G2.THE_CH.THE_HOLY_SPIRIT.b']::text[], 'States that Jesus promised his disciples the Holy Spirit and told them to wait in Jerusalem for the gift the Father promised (Acts 1:4), and mentions roles of the Holy Spirit in a Christian''s life: he strengthens (gives power, Luke 24:49), teaches and reminds (John 14:26), guides and comforts. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Jesus promised","a role of the Holy Spirit","where to wait"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'CRE.G1.CREATI.SELF_AWARENESS.a', 'outcome', 'essential', 'Knowing one is unique as God made one, from Grade 1. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'CRE.G1.CREATI.SELF_AWARENESS.b', 'outcome', 'essential', 'Stating one''s gender as God created. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'CRE.G1.CREATI.MY_FAMILY.a', 'outcome', 'essential', 'Naming members of their family, from Grade 1. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'CRE.G1.CREATI.MY_FAMILY.b', 'outcome', 'essential', 'Praying with family members. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
