INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES.M_C2_SELF_NOTHING', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'Thinks there is nothing good about himself because he is not the best in class.', '{"question":"Name one thing you like about yourself.","wrong_answer":"Nothing, I am not the best","correct_answer":"My smile (I can sing, I help my friends)"}'::jsonb, 'The child compares himself with the top pupils.', 'Offer "Nothing, I am not the best" beside "My smile (I can sing, I help my friends)" and ask the child to choose.', 'Read Psalm 139:13-14. Let each child say one good thing about a classmate, then about himself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES.M_C2_SELF_LOOKS_ONLY', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'Thinks only looks (fair skin, nice clothes) are good things about a person.', '{"question":"Is being kind something to like about yourself?","wrong_answer":"No, only how I look counts","correct_answer":"Yes, kindness is a good thing about me"}'::jsonb, 'Praise at home is often about looks.', 'Offer "No, only how I look counts" beside "Yes, kindness is a good thing about me" and ask the child to choose.', 'List good things we cannot see: kind, brave, helpful.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES.M_C2_SELF_CHORE_PLAY', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'Lists playing or watching TV as chores.', '{"question":"Which is a chore: sweeping or watching TV?","wrong_answer":"Watching TV","correct_answer":"Sweeping"}'::jsonb, 'Chore is a new word.', 'Offer "Watching TV" beside "Sweeping" and ask the child to choose.', 'A chore is a job that helps at home. Sort cards into chores and play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES.M_C2_SELF_PROUD', 'CRES.G2.CREATI.SELF_AWARENESS.SELF_LIKES', 'Thinks liking yourself means saying you are better than others.', '{"question":"Does liking yourself mean you are better than others?","wrong_answer":"Yes","correct_answer":"No, everyone is special to God"}'::jsonb, 'Self-praise is heard as boasting.', 'Offer "Yes" beside "No, everyone is special to God" and ask the child to choose.', 'Say: God made each person special; liking yourself and others go together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY.M_C2_EXT_FRIENDS', 'CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'Counts neighbours or friends as members of the extended family.', '{"question":"Is your neighbour part of your extended family?","wrong_answer":"Yes","correct_answer":"No, the extended family is relatives like grandparents and cousins"}'::jsonb, 'Close neighbours are called aunt or uncle.', 'Offer "Yes" beside "No, the extended family is relatives like grandparents and cousins" and ask the child to choose.', 'Draw the family tree. Neighbours are not on it, though we love them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY.M_C2_EXT_GRAND_NO', 'CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'Thinks grandparents are not family because they live far away.', '{"question":"Your grandmother lives in the village. Is she your family?","wrong_answer":"No, she lives far","correct_answer":"Yes, she is in my extended family"}'::jsonb, 'Family is pictured as people at home.', 'Offer "No, she lives far" beside "Yes, she is in my extended family" and ask the child to choose.', 'Put grandparents on the tree above parents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY.M_C2_EXT_CORNELIUS', 'CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'Thinks Cornelius worshipped God alone.', '{"question":"According to Acts 10:2, who worshipped God with Cornelius?","wrong_answer":"Nobody","correct_answer":"All his family"}'::jsonb, 'Bible people are often pictured alone.', 'Offer "Nobody" beside "All his family" and ask the child to choose.', 'Read Acts 10:2 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY.M_C2_EXT_COUSIN_SIS', 'CRES.G2.CREATI.MY_FAMILY.EXTENDED_FAMILY', 'Calls a cousin a sister.', '{"question":"Your uncle''s daughter is your...?","wrong_answer":"Sister","correct_answer":"Cousin"}'::jsonb, 'Cousins are called sisters at home.', 'Offer "Sister" beside "Cousin" and ask the child to choose.', 'Trace the line on the tree from uncle to his daughter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS.M_C2_SH_TOOTHBRUSH', 'CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS', 'Thinks sharing a toothbrush with a sibling is kind.', '{"question":"Should brothers share one toothbrush?","wrong_answer":"Yes, sharing is good","correct_answer":"No, a toothbrush should not be shared"}'::jsonb, 'Sharing is always praised.', 'Offer "Yes, sharing is good" beside "No, a toothbrush should not be shared" and ask the child to choose.', 'Say: some things carry germs from mouth to mouth. Kindness is giving your sibling his own.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS.M_C2_SH_RAZOR', 'CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS', 'Thinks a razor blade can be shared if it looks clean.', '{"question":"Can a family share one razor blade?","wrong_answer":"Yes, if it looks clean","correct_answer":"No, it can spread blood-borne disease"}'::jsonb, 'The danger cannot be seen.', 'Offer "Yes, if it looks clean" beside "No, it can spread blood-borne disease" and ask the child to choose.', 'Show the "never share" list. Blood can carry diseases.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS.M_C2_SH_NOTHING', 'CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS', 'Thinks nothing at home should be shared, so food is kept for oneself.', '{"question":"Should a family share food?","wrong_answer":"No, each keeps his own","correct_answer":"Yes, sharing food brings unity"}'::jsonb, 'The no-share rule is over-learnt.', 'Offer "No, each keeps his own" beside "Yes, sharing food brings unity" and ask the child to choose.', 'Sort into share (food, chairs) and do not share (toothbrush, towel).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS.M_C2_SH_TOWEL', 'CRES.G2.CREATI.MY_FAMILY.SHARED_ITEMS', 'Thinks a towel can be shared because it is washed.', '{"question":"Is a bathing towel shared or not?","wrong_answer":"Shared, it is washed","correct_answer":"Not shared"}'::jsonb, 'Washing seems to make anything shareable.', 'Offer "Shared, it is washed" beside "Not shared" and ask the child to choose.', 'A towel touches the body and can pass skin infections.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION.M_C2_SKY_PEOPLE', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'Thinks people or scientists made the sun and stars.', '{"question":"Who created the sun, moon and stars?","wrong_answer":"People","correct_answer":"God"}'::jsonb, 'Lights the child knows (bulbs) are made by people.', 'Offer "People" beside "God" and ask the child to choose.', 'Read Genesis 1:16. People make bulbs; God made the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION.M_C2_SKY_DAY_ONE', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'Says the sun was made on the first day.', '{"question":"On which day did God make the sun, moon and stars?","wrong_answer":"The first day","correct_answer":"The fourth day"}'::jsonb, 'Light was made on day one, so the sun seems to come first.', 'Offer "The first day" beside "The fourth day" and ask the child to choose.', 'Count the days of creation on fingers to four.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION.M_C2_SKY_SUN_NIGHT', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'Thinks the sun rules the night and the moon the day.', '{"question":"Which light rules the night?","wrong_answer":"The sun","correct_answer":"The moon"}'::jsonb, 'The two are mixed up.', 'Offer "The sun" beside "The moon" and ask the child to choose.', 'Draw a day sky and a night sky and place each light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION.M_C2_SKY_STARS_FEW', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.SKY_CREATION', 'Thinks the stars are only decorations with no purpose.', '{"question":"What are the lights in the sky for, says Genesis 1:14?","wrong_answer":"Only to look nice","correct_answer":"To mark days, seasons and years and give light"}'::jsonb, 'Stars are drawn as decorations.', 'Offer "Only to look nice" beside "To mark days, seasons and years and give light" and ask the child to choose.', 'Read Genesis 1:14 and link with days and seasons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE.M_C2_RB_PASTOR', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE', 'Thinks only pastors and adults need to read the Bible.', '{"question":"Can children read the Bible too?","wrong_answer":"No, only pastors","correct_answer":"Yes, children and families can read it"}'::jsonb, 'The child sees the Bible read by leaders.', 'Offer "No, only pastors" beside "Yes, children and families can read it" and ask the child to choose.', 'Show a children''s Bible and read a verse together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE.M_C2_RB_LAMP_REAL', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE', 'Thinks Psalm 119:105 means the Bible gives real light like a lamp.', '{"question":"What does \"your word is a lamp for my feet\" mean?","wrong_answer":"The Bible glows","correct_answer":"God''s word shows us the right way to live"}'::jsonb, 'Young children take words literally.', 'Offer "The Bible glows" beside "God''s word shows us the right way to live" and ask the child to choose.', 'Walk a dark path with a torch: it shows where to step. God''s word shows how to live.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE.M_C2_RB_STORIES', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE', 'Thinks we read the Bible only for nice stories.', '{"question":"Why do Christians read the Bible?","wrong_answer":"For fun stories only","correct_answer":"To learn about God and how to live"}'::jsonb, 'Bible lessons are often stories.', 'Offer "For fun stories only" beside "To learn about God and how to live" and ask the child to choose.', 'Name a story and its lesson for life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE.M_C2_RB_SUNDAY', 'CRES.G2.CREATI.CREATION_OF_THE_SKY_SUN_.READ_BIBLE', 'Thinks the Bible should be read only on Sunday.', '{"question":"When can a family read the Bible?","wrong_answer":"Only on Sunday","correct_answer":"Any day"}'::jsonb, 'Bible reading is seen in church on Sunday.', 'Offer "Only on Sunday" beside "Any day" and ask the child to choose.', 'Make a "verse of the day" chart for the week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT.M_C2_OT_27', 'CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT', 'Gives 27 or 66 as the number of Old Testament books.', '{"question":"How many books are in the Old Testament?","wrong_answer":"66","correct_answer":"39"}'::jsonb, 'Numbers of the whole Bible and the testaments are mixed.', 'Offer "66" beside "39" and ask the child to choose.', 'Write OT 39 on a long shelf drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT.M_C2_OT_MATTHEW', 'CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT', 'Names Matthew and Mark as the first two Old Testament books.', '{"question":"What are the first two books of the Old Testament?","wrong_answer":"Matthew and Mark","correct_answer":"Genesis and Exodus"}'::jsonb, 'Grade 1 taught Matthew and Mark as first books (of the New Testament).', 'Offer "Matthew and Mark" beside "Genesis and Exodus" and ask the child to choose.', 'Open the Bible at the very front: Genesis, Exodus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT.M_C2_OT_ORDER', 'CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT', 'Puts Exodus before Genesis.', '{"question":"Which book comes first, Genesis or Exodus?","wrong_answer":"Exodus","correct_answer":"Genesis"}'::jsonb, 'Both are new names.', 'Offer "Exodus" beside "Genesis" and ask the child to choose.', 'Genesis means beginning; it tells of creation, so it comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT.M_C2_OT_THREE_PARTS', 'CRES.G2.THE_HO.DIVISIONS_OF_THE_BIBLE.OLD_TESTAMENT', 'Thinks the Bible has three or more divisions.', '{"question":"How many divisions does the Bible have?","wrong_answer":"Three","correct_answer":"Two: the Old and the New Testament"}'::jsonb, 'Children hear many book names.', 'Offer "Three" beside "Two: the Old and the New Testament" and ask the child to choose.', 'Show a Bible with a ribbon between the two testaments.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL.M_C2_SAM_ELI_CALLED', 'CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL', 'Thinks it was Eli who called Samuel each time.', '{"question":"Who was calling Samuel?","wrong_answer":"Eli","correct_answer":"The Lord (God)"}'::jsonb, 'Samuel himself thought so.', 'Offer "Eli" beside "The Lord (God)" and ask the child to choose.', 'Read 1 Samuel 3:8. Eli understood it was the Lord.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL.M_C2_SAM_ONCE', 'CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL', 'Thinks God called only once.', '{"question":"How many times did Samuel run to Eli?","wrong_answer":"Once","correct_answer":"Three times"}'::jsonb, 'The repetition is not remembered.', 'Offer "Once" beside "Three times" and ask the child to choose.', 'Act it out with three runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL.M_C2_SAM_WORDS', 'CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL', 'Gives Samuel''s answer as "I am sleeping" or "Who is it?".', '{"question":"What did Samuel say when God called the last time?","wrong_answer":"Who is it?","correct_answer":"Speak, for your servant is listening"}'::jsonb, 'Natural night-time replies come to mind.', 'Offer "Who is it?" beside "Speak, for your servant is listening" and ask the child to choose.', 'Say the words together with a hand to the ear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL.M_C2_SAM_ADULT', 'CRES.G2.THE_HO.BIBLE_STORY_THE_CALL_OF_.SAMUEL', 'Thinks Samuel was an old man when God called him.', '{"question":"Was Samuel a boy or an old man when God called him?","wrong_answer":"An old man","correct_answer":"A boy"}'::jsonb, 'Prophets are pictured as old.', 'Offer "An old man" beside "A boy" and ask the child to choose.', 'Show a picture of the boy Samuel. God speaks to children too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL.M_C2_DAN_STOPPED', 'CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL', 'Thinks Daniel stopped praying to obey the king.', '{"question":"What did Daniel do after the new law?","wrong_answer":"Stopped praying","correct_answer":"Kept praying to God three times a day"}'::jsonb, 'Obeying the king seems right.', 'Offer "Stopped praying" beside "Kept praying to God three times a day" and ask the child to choose.', 'Read Daniel 6:10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL.M_C2_DAN_TIMES', 'CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL', 'Says Daniel prayed once a day or seven times.', '{"question":"How many times a day did Daniel pray?","wrong_answer":"Once","correct_answer":"Three times"}'::jsonb, 'Children guess familiar numbers.', 'Offer "Once" beside "Three times" and ask the child to choose.', 'Count three prayer times: morning, midday, evening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL.M_C2_DAN_FOUGHT', 'CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL', 'Thinks Daniel fought the lions or the lions were asleep.', '{"question":"Why did the lions not hurt Daniel?","wrong_answer":"He fought them","correct_answer":"God sent his angel and shut their mouths"}'::jsonb, 'Heroes in stories fight.', 'Offer "He fought them" beside "God sent his angel and shut their mouths" and ask the child to choose.', 'Read Daniel 6:22.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL.M_C2_DAN_KING_BAD', 'CRES.G2.THE_HO.BIBLE_STORY_DANIEL_IN_TH.DANIEL', 'Thinks King Darius wanted Daniel to die.', '{"question":"How did King Darius feel when Daniel was thrown in?","wrong_answer":"Happy","correct_answer":"Very sad; he could not sleep"}'::jsonb, 'The king made the law, so he seems the villain.', 'Offer "Happy" beside "Very sad; he could not sleep" and ask the child to choose.', 'Read Daniel 6:14, 18. The officials tricked him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH.M_C2_WID_PLENTY', 'CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH', 'Thinks the widow had plenty of food.', '{"question":"How much food did the widow have?","wrong_answer":"Plenty","correct_answer":"Only a handful of flour and a little oil"}'::jsonb, 'Generous people are pictured as rich.', 'Offer "Plenty" beside "Only a handful of flour and a little oil" and ask the child to choose.', 'Show a tiny handful of flour. Read 1 Kings 17:12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH.M_C2_WID_SELFISH', 'CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH', 'Thinks Elijah was greedy to ask for bread first.', '{"question":"Why did Elijah ask for bread first?","wrong_answer":"He was greedy","correct_answer":"To test her trust; God promised the flour and oil would not run out"}'::jsonb, 'Asking first looks rude.', 'Offer "He was greedy" beside "To test her trust; God promised the flour and oil would not run out" and ask the child to choose.', 'Read 1 Kings 17:13-14. Elijah gave God''s promise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH.M_C2_WID_RAN_OUT', 'CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH', 'Thinks the flour ran out the next day.', '{"question":"What happened to the flour and oil?","wrong_answer":"They ran out","correct_answer":"They did not run out until the rain came"}'::jsonb, 'Food always runs out at home.', 'Offer "They ran out" beside "They did not run out until the rain came" and ask the child to choose.', 'Read 1 Kings 17:16.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH.M_C2_WID_JESUS', 'CRES.G2.THE_HO.THE_BIBLE_STORY_THE_WIDO.WIDOW_ZAREPHATH', 'Thinks Jesus was the visitor.', '{"question":"Which prophet visited the widow?","wrong_answer":"Jesus","correct_answer":"Elijah"}'::jsonb, 'Miracle stories are linked with Jesus.', 'Offer "Jesus" beside "Elijah" and ask the child to choose.', 'Name the prophet on a card: Elijah.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS.M_C2_SHP_AFRAID_STAY', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS', 'Thinks the shepherds stayed in the fields because they were afraid.', '{"question":"What did the shepherds do after the angels left?","wrong_answer":"Stayed in the fields","correct_answer":"Hurried to Bethlehem to see the baby"}'::jsonb, 'Shepherds stay with sheep.', 'Offer "Stayed in the fields" beside "Hurried to Bethlehem to see the baby" and ask the child to choose.', 'Read Luke 2:15-16.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS.M_C2_SHP_GIFTS', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS', 'Thinks the shepherds brought gold and gifts.', '{"question":"Who brought gold to Jesus: the shepherds or the wise men?","wrong_answer":"The shepherds","correct_answer":"The wise men"}'::jsonb, 'All visitors are mixed in nativity plays.', 'Offer "The shepherds" beside "The wise men" and ask the child to choose.', 'Two cards: shepherds praised; wise men brought gifts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS.M_C2_SHP_KEPT_QUIET', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS', 'Thinks the shepherds kept the news secret.', '{"question":"What did the shepherds do after seeing Jesus?","wrong_answer":"Kept it secret","correct_answer":"Told everyone and praised God"}'::jsonb, 'Not every story ends with telling.', 'Offer "Kept it secret" beside "Told everyone and praised God" and ask the child to choose.', 'Read Luke 2:17, 20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS.M_C2_SHP_PALACE', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.SHEPHERDS', 'Thinks they found Jesus in a palace.', '{"question":"Where did the shepherds find baby Jesus?","wrong_answer":"In a palace","correct_answer":"Lying in a manger"}'::jsonb, 'A king is born in a palace.', 'Offer "In a palace" beside "Lying in a manger" and ask the child to choose.', 'Show a manger: an animal feeding box.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION.M_C2_DED_CHURCH', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION', 'Thinks Jesus was dedicated in a church like ours.', '{"question":"Where was baby Jesus presented to the Lord?","wrong_answer":"In a church","correct_answer":"In the temple in Jerusalem"}'::jsonb, 'Children know dedication in their own church.', 'Offer "In a church" beside "In the temple in Jerusalem" and ask the child to choose.', 'Show a picture of the temple. Read Luke 2:22.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION.M_C2_DED_LAMB', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION', 'Says Mary and Joseph offered a lamb or money.', '{"question":"What did Mary and Joseph offer?","wrong_answer":"A lamb","correct_answer":"A pair of doves or two young pigeons"}'::jsonb, 'Lambs are the best-known sacrifice.', 'Offer "A lamb" beside "A pair of doves or two young pigeons" and ask the child to choose.', 'Read Luke 2:24 and draw two doves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION.M_C2_DED_TEACHER', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION', 'Mixes the dedication with Jesus at twelve teaching in the temple.', '{"question":"How old was Jesus when he was dedicated?","wrong_answer":"Twelve years","correct_answer":"A baby"}'::jsonb, 'Both stories are in the temple.', 'Offer "Twelve years" beside "A baby" and ask the child to choose.', 'Put two pictures side by side: baby Jesus and Jesus at twelve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION.M_C2_DED_SIMEON', 'CRES.G2.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.DEDICATION', 'Thinks Herod or a priest named Eli held the baby.', '{"question":"Who took baby Jesus in his arms and praised God?","wrong_answer":"King Herod","correct_answer":"Simeon"}'::jsonb, 'Familiar names from other stories come to mind.', 'Offer "King Herod" beside "Simeon" and ask the child to choose.', 'Read Luke 2:28 with a name card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS.M_C2_WG_MONEY', 'CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS', 'Names money or toys as the wise men''s gifts.', '{"question":"Which gifts did the wise men give Jesus?","wrong_answer":"Money and toys","correct_answer":"Gold, frankincense and myrrh"}'::jsonb, 'Gifts the child knows are money and toys.', 'Offer "Money and toys" beside "Gold, frankincense and myrrh" and ask the child to choose.', 'Show three boxes labelled with the gifts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS.M_C2_WG_STRANGER_OK', 'CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS', 'Thinks taking a gift from a stranger is fine because the wise men gave gifts.', '{"question":"A stranger offers you a gift on the way home. What do you do?","wrong_answer":"Take it, like baby Jesus got gifts","correct_answer":"Say no thank you and tell a trusted adult"}'::jsonb, 'The child links gifts with good people.', 'Offer "Take it, like baby Jesus got gifts" beside "Say no thank you and tell a trusted adult" and ask the child to choose.', 'Separate the story from the rule. Practise "No, thank you" and telling a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS.M_C2_WG_FOUR', 'CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS', 'Names four or two gifts.', '{"question":"How many kinds of gifts did the wise men bring?","wrong_answer":"Two","correct_answer":"Three"}'::jsonb, 'Number is forgotten.', 'Offer "Two" beside "Three" and ask the child to choose.', 'Count on three fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS.M_C2_WG_SHEPHERDS', 'CRES.G2.THE_EA.KINDNESS_OF_THE_WISE_MEN.WISE_GIFTS', 'Thinks the shepherds gave the gold.', '{"question":"Who gave gold to Jesus?","wrong_answer":"The shepherds","correct_answer":"The wise men"}'::jsonb, 'All Christmas visitors are mixed.', 'Offer "The shepherds" beside "The wise men" and ask the child to choose.', 'Match visitors to what they did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM.M_C2_STM_AWAKE', 'CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM', 'Thinks Jesus was awake and steering the boat.', '{"question":"What was Jesus doing when the storm began?","wrong_answer":"Steering the boat","correct_answer":"Sleeping"}'::jsonb, 'The leader is pictured in charge.', 'Offer "Steering the boat" beside "Sleeping" and ask the child to choose.', 'Read Matthew 8:24.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM.M_C2_STM_SWAM', 'CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM', 'Thinks the disciples swam to shore.', '{"question":"How did the storm end?","wrong_answer":"They swam to shore","correct_answer":"Jesus rebuked the wind and waves and it became calm"}'::jsonb, 'Escaping danger means swimming in the child''s mind.', 'Offer "They swam to shore" beside "Jesus rebuked the wind and waves and it became calm" and ask the child to choose.', 'Read Matthew 8:26.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM.M_C2_STM_PETER', 'CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM', 'Mixes it with Peter walking on water.', '{"question":"In the calming of the storm, did Peter walk on water?","wrong_answer":"Yes","correct_answer":"No, Jesus calmed the storm from the boat"}'::jsonb, 'Both stories have a boat and wind.', 'Offer "Yes" beside "No, Jesus calmed the storm from the boat" and ask the child to choose.', 'Compare the two pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM.M_C2_STM_FEAR_BAD', 'CRES.G2.THE_EA.JESUS_CALMS_THE_STORM.CALMS_STORM', 'Thinks being afraid is a sin, so the disciples were bad.', '{"question":"What should we do when we are afraid?","wrong_answer":"Hide it, fear is bad","correct_answer":"Call on Jesus and trust him"}'::jsonb, 'The child hears "why are you afraid" as a scolding.', 'Offer "Hide it, fear is bad" beside "Call on Jesus and trust him" and ask the child to choose.', 'Say: the disciples called on Jesus and he helped. We can too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH.M_C2_CF_CAUGHT_NIGHT', 'CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH', 'Thinks the fishermen had caught many fish in the night.', '{"question":"How many fish had Simon caught during the night?","wrong_answer":"Many","correct_answer":"None"}'::jsonb, 'Fishermen are expected to catch fish.', 'Offer "Many" beside "None" and ask the child to choose.', 'Read Luke 5:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH.M_C2_CF_SHALLOW', 'CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH', 'Thinks Jesus told them to fish near the shore.', '{"question":"Where did Jesus tell Simon to let down the nets?","wrong_answer":"Near the shore","correct_answer":"In deep water"}'::jsonb, 'Easy places seem better.', 'Offer "Near the shore" beside "In deep water" and ask the child to choose.', 'Read Luke 5:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH.M_C2_CF_ONE_BOAT', 'CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH', 'Thinks the fish filled only a small basket.', '{"question":"How many fish did they catch?","wrong_answer":"A small basket","correct_answer":"So many that two boats began to sink"}'::jsonb, 'Catches the child has seen are small.', 'Offer "A small basket" beside "So many that two boats began to sink" and ask the child to choose.', 'Read Luke 5:6-7 and draw two overloaded boats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH.M_C2_CF_REFUSED', 'CRES.G2.THE_EA.MIRACULOUS_CATCH_OF_FISH.CATCH_FISH', 'Thinks Simon refused because he was tired.', '{"question":"What did Simon do when Jesus told him to fish again?","wrong_answer":"Refused, he was tired","correct_answer":"Obeyed: \"Because you say so, I will\""}'::jsonb, 'Tired people refuse.', 'Offer "Refused, he was tired" beside "Obeyed: "Because you say so, I will"" and ask the child to choose.', 'Read Luke 5:5 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND.M_C2_WH_LEG', 'CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND', 'Thinks the man had a bad leg or blind eyes.', '{"question":"What was wrong with the man?","wrong_answer":"He was blind","correct_answer":"His hand was withered (shrivelled)"}'::jsonb, 'Healing stories are mixed.', 'Offer "He was blind" beside "His hand was withered (shrivelled)" and ask the child to choose.', 'Show a picture and read Matthew 12:10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND.M_C2_WH_MARKET', 'CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND', 'Thinks it happened in the market.', '{"question":"Where was the man healed?","wrong_answer":"In the market","correct_answer":"In the synagogue"}'::jsonb, 'Many miracles happened outdoors.', 'Offer "In the market" beside "In the synagogue" and ask the child to choose.', 'Read Matthew 12:9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND.M_C2_WH_SABBATH_WRONG', 'CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND', 'Thinks Jesus did wrong by healing on the Sabbath.', '{"question":"Was it right for Jesus to heal on the Sabbath?","wrong_answer":"No, it broke the rule","correct_answer":"Yes, it is lawful to do good on the Sabbath"}'::jsonb, 'The Pharisees'' complaint sounds right.', 'Offer "No, it broke the rule" beside "Yes, it is lawful to do good on the Sabbath" and ask the child to choose.', 'Read Matthew 12:11-12: the sheep in a pit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND.M_C2_WH_TOUCH', 'CRES.G2.THE_EA.HEALING_THE_MAN_WITH_A_W.WITHERED_HAND', 'Thinks Jesus rubbed medicine on the hand.', '{"question":"How did Jesus heal the hand?","wrong_answer":"With medicine","correct_answer":"He said \"Stretch out your hand\" and it was restored"}'::jsonb, 'Healing at home uses medicine.', 'Offer "With medicine" beside "He said "Stretch out your hand" and it was restored" and ask the child to choose.', 'Read Matthew 12:13 and act it out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.EASTER.EASTER_LOVE.M_C2_EL_BAD_MAN', 'CRES.G2.THE_EA.EASTER.EASTER_LOVE', 'Thinks Jesus died because he did something wrong.', '{"question":"Why did Jesus die on the cross?","wrong_answer":"He did something wrong","correct_answer":"Because of God''s great love for people"}'::jsonb, 'In the child''s world, punishment follows wrongdoing.', 'Offer "He did something wrong" beside "Because of God''s great love for people" and ask the child to choose.', 'Read John 3:16 in simple words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.EASTER.EASTER_LOVE.M_C2_EL_STAYED_DEAD', 'CRES.G2.THE_EA.EASTER.EASTER_LOVE', 'Thinks Jesus stayed in the tomb.', '{"question":"What happened on the third day?","wrong_answer":"He stayed in the tomb","correct_answer":"He was raised from the dead"}'::jsonb, 'Death seems final.', 'Offer "He stayed in the tomb" beside "He was raised from the dead" and ask the child to choose.', 'Read 1 Corinthians 15:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.EASTER.EASTER_LOVE.M_C2_EL_EGGS_ONLY', 'CRES.G2.THE_EA.EASTER.EASTER_LOVE', 'Lists only buying new clothes or eating chicken as Easter activities in church.', '{"question":"Name an activity done in church at Easter.","wrong_answer":"Eating chicken","correct_answer":"Prayers (singing, special services)"}'::jsonb, 'Holiday food is what the child remembers.', 'Offer "Eating chicken" beside "Prayers (singing, special services)" and ask the child to choose.', 'List church activities and home activities separately.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_EA.EASTER.EASTER_LOVE.M_C2_EL_CHRISTMAS', 'CRES.G2.THE_EA.EASTER.EASTER_LOVE', 'Thinks Easter is when Jesus was born.', '{"question":"Is Easter about Jesus'' birth?","wrong_answer":"Yes","correct_answer":"No, it is about his death and resurrection"}'::jsonb, 'Church holidays are mixed.', 'Offer "Yes" beside "No, it is about his death and resurrection" and ask the child to choose.', 'Put Christmas and Easter cards side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.SHARING.SCHOOL_SHARING.M_C2_SS_NONE', 'CRES.G2.CHRIST.SHARING.SCHOOL_SHARING', 'Thinks nothing at school is shared because each pupil has his own things.', '{"question":"Name something shared at school.","wrong_answer":"Nothing","correct_answer":"Books (desks, balls, crayons)"}'::jsonb, 'Pupils are told "mind your own things".', 'Offer "Nothing" beside "Books (desks, balls, crayons)" and ask the child to choose.', 'Walk around the class naming shared things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.SHARING.SCHOOL_SHARING.M_C2_SS_GRAB', 'CRES.G2.CHRIST.SHARING.SCHOOL_SHARING', 'Thinks sharing means taking a friend''s things when you want.', '{"question":"Is taking a friend''s crayon without asking sharing?","wrong_answer":"Yes","correct_answer":"No, sharing is giving or asking politely"}'::jsonb, 'The child confuses sharing with taking.', 'Offer "Yes" beside "No, sharing is giving or asking politely" and ask the child to choose.', 'Role-play asking and offering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.SHARING.SCHOOL_SHARING.M_C2_SS_FRIENDS_ONLY', 'CRES.G2.CHRIST.SHARING.SCHOOL_SHARING', 'Thinks we share only with our best friends.', '{"question":"Should you share with a new pupil?","wrong_answer":"No, only with my friends","correct_answer":"Yes, share with everyone"}'::jsonb, 'Children share with their circle.', 'Offer "No, only with my friends" beside "Yes, share with everyone" and ask the child to choose.', 'Talk about how a new pupil feels. Share with all.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.SHARING.SCHOOL_SHARING.M_C2_SS_BOTTLE', 'CRES.G2.CHRIST.SHARING.SCHOOL_SHARING', 'Thinks drinking from a friend''s bottle is good sharing.', '{"question":"Should you drink from your friend''s water bottle?","wrong_answer":"Yes, it is sharing","correct_answer":"No, pour into your own cup"}'::jsonb, 'Sharing is praised everywhere.', 'Offer "Yes, it is sharing" beside "No, pour into your own cup" and ask the child to choose.', 'Show pouring into a cup instead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS.M_C2_OB_ONLY_WATCHED', 'CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS', 'Obeys only when the teacher is watching.', '{"question":"The teacher leaves the class. Should you keep working?","wrong_answer":"No, she is not watching","correct_answer":"Yes, obey even when no one watches"}'::jsonb, 'Children obey to avoid punishment.', 'Offer "No, she is not watching" beside "Yes, obey even when no one watches" and ask the child to choose.', 'Talk about God seeing and doing right always.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS.M_C2_OB_PREFECT', 'CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS', 'Thinks pupils need not obey the children''s government because they are children too.', '{"question":"Should you obey the class monitor?","wrong_answer":"No, she is a child like me","correct_answer":"Yes, she is a leader chosen to help"}'::jsonb, 'Leaders are pictured as adults.', 'Offer "No, she is a child like me" beside "Yes, she is a leader chosen to help" and ask the child to choose.', 'Read Hebrews 13:17. Leaders keep order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS.M_C2_OB_FEAR', 'CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS', 'Thinks the only reason to obey is fear of punishment.', '{"question":"Why should we obey our teachers?","wrong_answer":"So we are not beaten","correct_answer":"They guide us and God asks us to obey leaders"}'::jsonb, 'Punishment is the reason the child hears most.', 'Offer "So we are not beaten" beside "They guide us and God asks us to obey leaders" and ask the child to choose.', 'List reasons: learning, safety, order, pleasing God.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS.M_C2_OB_WRONG_ORDER', 'CRES.G2.CHRIST.OBEDIENCE.OBEY_TEACHERS', 'Thinks a child must obey anyone, even when told to do something unsafe or wrong.', '{"question":"An older pupil tells you to steal a pen. Should you obey?","wrong_answer":"Yes, obey older pupils","correct_answer":"No, say no and tell a teacher"}'::jsonb, 'Obedience is taught without limits.', 'Offer "Yes, obey older pupils" beside "No, say no and tell a teacher" and ask the child to choose.', 'Say: we obey good instructions. If anyone asks you to do wrong or unsafe things, say no and tell a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.HONESTY.TELL_TRUTH.M_C2_TT_SMALL_LIE', 'CRES.G2.CHRIST.HONESTY.TELL_TRUTH', 'Thinks a small lie is fine if it stops trouble.', '{"question":"You broke a cup. Should you say the cat did it?","wrong_answer":"Yes, to avoid trouble","correct_answer":"No, tell the truth"}'::jsonb, 'Small lies seem harmless and helpful.', 'Offer "Yes, to avoid trouble" beside "No, tell the truth" and ask the child to choose.', 'Show how one lie needs another. Praise owning up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.HONESTY.TELL_TRUTH.M_C2_TT_COPY', 'CRES.G2.CHRIST.HONESTY.TELL_TRUTH', 'Thinks copying a friend''s work is fine if you get it right.', '{"question":"Is copying your friend''s homework honest?","wrong_answer":"Yes, the answer is right","correct_answer":"No, it is dishonest"}'::jsonb, 'Getting answers right is praised.', 'Offer "Yes, the answer is right" beside "No, it is dishonest" and ask the child to choose.', 'Say: the teacher needs to see what you know to help you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.HONESTY.TELL_TRUTH.M_C2_TT_FOUND_KEEP', 'CRES.G2.CHRIST.HONESTY.TELL_TRUTH', 'Thinks found items can be kept.', '{"question":"You find a pencil case in the field. What is honest?","wrong_answer":"Keep it","correct_answer":"Give it to the teacher"}'::jsonb, '"Finders keepers" is a game rule.', 'Offer "Keep it" beside "Give it to the teacher" and ask the child to choose.', 'Role-play returning it. Ask how the owner feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.HONESTY.TELL_TRUTH.M_C2_TT_CAUGHT', 'CRES.G2.CHRIST.HONESTY.TELL_TRUTH', 'Thinks lying is wrong only if you are caught.', '{"question":"Is a lie wrong if nobody finds out?","wrong_answer":"No","correct_answer":"Yes, God knows and lying is wrong"}'::jsonb, 'Children fear being caught.', 'Offer "No" beside "Yes, God knows and lying is wrong" and ask the child to choose.', 'Read Proverbs 12:19 and talk about God seeing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS.M_C2_TO_BIG_GIFTS', 'CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS', 'Thinks thank you is only for big gifts.', '{"question":"Should you say thank you when a friend lends you a pencil?","wrong_answer":"No, it is small","correct_answer":"Yes"}'::jsonb, 'Thank you is linked with presents.', 'Offer "No, it is small" beside "Yes" and ask the child to choose.', 'Practise thanking for small things all day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS.M_C2_TO_PARENTS_DUTY', 'CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS', 'Thinks parents need not be thanked because it is their duty.', '{"question":"Should you thank your mother for cooking?","wrong_answer":"No, it is her job","correct_answer":"Yes"}'::jsonb, 'Duties seem not to need thanks.', 'Offer "No, it is her job" beside "Yes" and ask the child to choose.', 'Ask how mother feels when thanked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS.M_C2_TO_WORDS_ONLY', 'CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS', 'Thinks thanking can only be done with words.', '{"question":"Name another way to thank someone apart from words.","wrong_answer":"There is none","correct_answer":"Help them (make a card, give a hug)"}'::jsonb, 'Thanks is taught as a phrase.', 'Offer "There is none" beside "Help them (make a card, give a hug)" and ask the child to choose.', 'Make thank-you cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS.M_C2_TO_ONLY_GOD', 'CRES.G2.CHRIST.THANKFULNESS.THANK_OTHERS', 'Thinks we thank only God, not people.', '{"question":"Should we thank people as well as God?","wrong_answer":"No, only God","correct_answer":"Yes, both"}'::jsonb, 'Thanksgiving is taught in prayers.', 'Offer "No, only God" beside "Yes, both" and ask the child to choose.', 'Read 1 Thessalonians 5:18 and role-play thanking a friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON.M_C2_PS_FATHER_ANGRY', 'CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON', 'Thinks the father punished or chased the son away.', '{"question":"What did the father do when his son came home?","wrong_answer":"He chased him away","correct_answer":"He ran to him, hugged him and held a feast"}'::jsonb, 'Children expect punishment for wrongdoing.', 'Offer "He chased him away" beside "He ran to him, hugged him and held a feast" and ask the child to choose.', 'Read Luke 15:20-24 and act it out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON.M_C2_PS_ELDER', 'CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON', 'Thinks the elder son went away.', '{"question":"Which son went to a distant country?","wrong_answer":"The elder son","correct_answer":"The younger son"}'::jsonb, 'Order of sons is confused.', 'Offer "The elder son" beside "The younger son" and ask the child to choose.', 'Two name cards: younger went away, elder stayed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON.M_C2_PS_COWS', 'CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON', 'Thinks he looked after cows or goats.', '{"question":"What animals did the son feed?","wrong_answer":"Cows","correct_answer":"Pigs"}'::jsonb, 'Local herding is of cattle.', 'Offer "Cows" beside "Pigs" and ask the child to choose.', 'Read Luke 15:15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON.M_C2_PS_LESSON_MONEY', 'CRES.G2.CHRIST.FORGIVENESS.PRODIGAL_SON', 'Gives "save money" as the only lesson.', '{"question":"What is the main lesson of the prodigal son?","wrong_answer":"Save your money","correct_answer":"God forgives us and we should forgive others"}'::jsonb, 'Wasting money stands out.', 'Offer "Save your money" beside "God forgives us and we should forgive others" and ask the child to choose.', 'Ask: what did the father do? The lesson is there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS.M_C2_SI_PARENTS_BUY', 'CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS', 'Thinks lost items do not matter because parents will buy new ones.', '{"question":"You lose your ruler. Does it matter?","wrong_answer":"No, mother will buy another","correct_answer":"Yes, it costs money; take care of your things"}'::jsonb, 'Children do not see the cost.', 'Offer "No, mother will buy another" beside "Yes, it costs money; take care of your things" and ask the child to choose.', 'Talk about what a ruler costs and what else that money buys.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS.M_C2_SI_BAG_FLOOR', 'CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS', 'Thinks books can be left on the floor or field.', '{"question":"Where should you keep your books?","wrong_answer":"Anywhere, on the floor","correct_answer":"In my bag or desk"}'::jsonb, 'Children put things down wherever they are.', 'Offer "Anywhere, on the floor" beside "In my bag or desk" and ask the child to choose.', 'Practise packing a bag neatly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS.M_C2_SI_TEACHER_JOB', 'CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS', 'Thinks it is the teacher''s job to care for pupils'' items.', '{"question":"Who should take care of your books?","wrong_answer":"The teacher","correct_answer":"Me"}'::jsonb, 'Teachers often look after things.', 'Offer "The teacher" beside "Me" and ask the child to choose.', 'Read Colossians 3:23. Each one cares for his own things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS.M_C2_SI_LABEL', 'CRES.G2.CHRIST.RESPONSIBILITY.SCHOOL_ITEMS', 'Does not see why items should be labelled.', '{"question":"Why write your name on your books?","wrong_answer":"There is no reason","correct_answer":"So they can be returned if lost"}'::jsonb, 'Labels seem like decoration.', 'Offer "There is no reason" beside "So they can be returned if lost" and ask the child to choose.', 'Pick up an unlabelled pencil: whose is it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.WORK.HELP_PARENTS.M_C2_HP_PLAY', 'CRES.G2.CHRIST.WORK.HELP_PARENTS', 'Lists playing with toys as a way of helping parents.', '{"question":"Which helps your parents: washing cups or playing with a ball?","wrong_answer":"Playing with a ball","correct_answer":"Washing cups"}'::jsonb, 'Being out of the way feels like helping.', 'Offer "Playing with a ball" beside "Washing cups" and ask the child to choose.', 'Sort cards into helping and playing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.WORK.HELP_PARENTS.M_C2_HP_HEAVY', 'CRES.G2.CHRIST.WORK.HELP_PARENTS', 'Thinks children should do heavy or dangerous jobs like using a panga or cooking alone.', '{"question":"Is it safe for a seven-year-old to cook alone on the jiko?","wrong_answer":"Yes, to help","correct_answer":"No, help with safe jobs only"}'::jsonb, 'Children want to do grown-up jobs.', 'Offer "Yes, to help" beside "No, help with safe jobs only" and ask the child to choose.', 'List safe jobs for a child and jobs for adults.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.WORK.HELP_PARENTS.M_C2_HP_GIRLS', 'CRES.G2.CHRIST.WORK.HELP_PARENTS', 'Thinks only girls help in the kitchen.', '{"question":"Can boys wash utensils?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Jobs at home are often split.', 'Offer "No" beside "Yes" and ask the child to choose.', 'List jobs: everyone can do them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.CHRIST.WORK.HELP_PARENTS.M_C2_HP_LAZY_OK', 'CRES.G2.CHRIST.WORK.HELP_PARENTS', 'Thinks work is a punishment.', '{"question":"Is work good or a punishment?","wrong_answer":"A punishment","correct_answer":"Good; it helps the family"}'::jsonb, 'Chores are sometimes given as punishment.', 'Offer "A punishment" beside "Good; it helps the family" and ask the child to choose.', 'Read Colossians 3:23. Praise children who help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT.M_C2_FM_THREE', 'CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT', 'Says he asked for one loaf or money.', '{"question":"What did the man ask his friend for?","wrong_answer":"Money","correct_answer":"Three loaves of bread"}'::jsonb, 'Borrowing is pictured as money.', 'Offer "Money" beside "Three loaves of bread" and ask the child to choose.', 'Read Luke 11:5 and hold up three paper loaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT.M_C2_FM_FIRST', 'CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT', 'Thinks the friend got up at once.', '{"question":"Why did the friend finally get up?","wrong_answer":"He got up at once","correct_answer":"Because the man kept on asking"}'::jsonb, 'Good friends are expected to help at once.', 'Offer "He got up at once" beside "Because the man kept on asking" and ask the child to choose.', 'Read Luke 11:8 and act out knocking again and again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT.M_C2_FM_LESSON', 'CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT', 'Thinks the lesson is "do not disturb people at night".', '{"question":"What does the story teach about prayer?","wrong_answer":"Do not disturb people at night","correct_answer":"Keep on praying; ask and it will be given"}'::jsonb, 'The rude timing stands out.', 'Offer "Do not disturb people at night" beside "Keep on praying; ask and it will be given" and ask the child to choose.', 'Read Luke 11:9-10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT.M_C2_FM_LP_START', 'CRES.G2.THE_CH.PRAYER.FRIEND_MIDNIGHT', 'Starts the Lord''s Prayer with "Give us this day".', '{"question":"How does the Lord''s Prayer begin?","wrong_answer":"Give us today our daily bread","correct_answer":"Our Father in heaven"}'::jsonb, 'The bread line is the most concrete.', 'Offer "Give us today our daily bread" beside "Our Father in heaven" and ask the child to choose.', 'Say the first four lines with actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE.M_C2_HSP_MONEY', 'CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE', 'Thinks Jesus promised money or houses.', '{"question":"What did Jesus promise his disciples in Acts 1:4?","wrong_answer":"Money","correct_answer":"The gift of the Holy Spirit"}'::jsonb, 'Promises at home are often about things.', 'Offer "Money" beside "The gift of the Holy Spirit" and ask the child to choose.', 'Read Acts 1:4-5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE.M_C2_HSP_GO_HOME', 'CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE', 'Thinks Jesus told the disciples to go home.', '{"question":"Where did Jesus tell the disciples to wait?","wrong_answer":"At their homes","correct_answer":"In Jerusalem"}'::jsonb, 'Waiting is done at home.', 'Offer "At their homes" beside "In Jerusalem" and ask the child to choose.', 'Read Acts 1:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE.M_C2_HSP_ROLE_PUNISH', 'CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE', 'Thinks the Holy Spirit punishes children who do wrong.', '{"question":"Name a role of the Holy Spirit.","wrong_answer":"He punishes us","correct_answer":"He helps (teaches, guides, strengthens) us"}'::jsonb, 'Unseen powers are pictured as scary.', 'Offer "He punishes us" beside "He helps (teaches, guides, strengthens) us" and ask the child to choose.', 'Read John 14:26: the Helper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE.M_C2_HSP_PROMISE_BROKEN', 'CRES.G2.THE_CH.THE_HOLY_SPIRIT.HS_PROMISE', 'Thinks a promise does not have to be kept, so Jesus'' promise may not come true.', '{"question":"Did Jesus keep his promise to send the Holy Spirit?","wrong_answer":"No","correct_answer":"Yes, at Pentecost (Acts 2)"}'::jsonb, 'Children see promises broken.', 'Offer "No" beside "Yes, at Pentecost (Acts 2)" and ask the child to choose.', 'Read Acts 2:4 briefly: the promise kept.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
